function Q(topicId, question, options, answer, explanation) {
  return { topicId, question, options, answer, explanation };
}

const QUESTIONS = [
  Q("signal-area", "A horizontal red square panel with ONE yellow diagonal, displayed in the signals area, means:", ["Special precautions must be observed when approaching to land or landing, due to the poor state of the manoeuvring area", "The aerodrome is unsafe for the movement of aircraft and landing is prohibited", "Glider flying is in progress", "Aircraft must use hard surfaces only"], 0, "One diagonal = take special care. Two diagonals forming a cross = landing prohibited."),
  Q("signal-area", "A horizontal red square panel with yellow diagonals (a yellow cross) means:", ["The aerodrome is unsafe for the movement of aircraft and landing is prohibited, and the prohibition is liable to continue", "Take special care when landing", "A right-hand circuit is in force", "Helicopters only"], 0, "The cross 'crosses out' the aerodrome: no landing."),
  Q("signal-area", "A horizontal white dumb-bell in the signals area indicates:", ["Aircraft must land, take off and taxi on hard surfaces only", "Aircraft must land and take off on runways only, but may taxi on grass", "Glider flying is in progress", "Light aircraft may use the grass area"], 0, "A plain dumb-bell confines ALL ground movement to paved/hard surfaces."),
  Q("signal-area", "A white dumb-bell with a black stripe across each disc, at right angles to the shaft, means:", ["Take-off and landing on runways only, but other ground movements need not be confined to hard surfaces", "All movements are confined to hard surfaces", "The aerodrome is closed", "Glider launching is taking place"], 0, "The stripes relax the rule: only take-off & landing must be on runways."),
  Q("signal-area", "Which signals indicate that glider flying is in progress?", ["A white double cross in the signals area or two red balls on a mast", "A black ball on a mast", "A red and yellow striped arrow", "A white letter L"], 0, "Double cross (ground) and two red balls (mast) both mean gliding."),
  Q("signal-area", "When a white landing T is displayed, you should land:", ["Parallel to the shaft of the T, towards the cross-arm", "Parallel to the cross-arm", "Along the shaft, away from the cross-arm", "In any direction into wind"], 0, "Land along the shaft, heading towards the cross-arm."),
  Q("signal-area", "A black letter C on a yellow background indicates:", ["The location of the ATS reporting office", "That customs facilities are available", "A clearway", "A closed taxiway"], 0, "C marks where pilots report to the ATSU."),
  Q("signal-area", "A red and yellow chequered flag or board displayed at an aerodrome means:", ["Aircraft may move on the manoeuvring area and apron only in accordance with ATC permission", "A fire service is available", "The aerodrome is closed", "Customs clearance is required"], 0, "The chequered board means ATC permission is needed for any movement."),
  Q("signal-area", "A red and yellow striped arrow bent through 90°, or a rectangular green flag on a mast, indicates:", ["A right-hand circuit is in force", "A left-hand circuit is in force", "The runway is closed", "Glider winching is taking place"], 0, "Left-hand circuits are standard; the striped arrow/green flag signals a right-hand circuit."),
  Q("signal-area", "A black ball suspended from a mast means:", ["The directions of take-off and landing are not necessarily the same", "Glider flying is in progress", "The aerodrome is closed to non-radio aircraft", "A right-hand circuit is in force"], 0, "Black ball (mast) = white disc by the T (ground): take-off and landing directions may differ."),
  Q("signal-area", "A white letter H in the signals area indicates:", ["Helicopters shall take off and land only within the area designated", "A hospital is nearby", "Hold position", "Heavy aircraft are operating"], 0, "H = helicopter area."),
  Q("signal-area", "Where is the signals area normally located?", ["Near the control tower, where it is visible from the air", "At the threshold of the main runway", "Beyond the end of the stopway", "On the apron next to the fuel pumps"], 0, "It's normally near the tower/ATSU and designed to be read from overhead."),

  Q("notification-of-arrival", "You filed a flight plan but divert and land at a different aerodrome. To prevent search and rescue action you should inform ATS:", ["Within 30 minutes of your ETA at the original destination", "Within 1 hour of landing", "Within 24 hours", "Only if your flight crossed controlled airspace"], 0, "After 30 minutes beyond ETA with no arrival report, the alerting service may begin overdue action."),
  Q("notification-of-arrival", "You land at an aerodrome with no ATS unit on a flight for which a flight plan was filed. The arrival report should be made:", ["As soon as practicable after landing, by the quickest means available, to the nearest ATS unit", "By post within 7 days", "Only if requested by ATC", "To the aerodrome owner only"], 0, "SERA.4020: quickest means (normally phone) to the nearest ATS unit."),
  Q("notification-of-arrival", "Who is responsible for closing a flight plan?", ["The pilot-in-command", "The departure ATSU", "The aircraft owner", "The destination aerodrome operator"], 0, "It is the PIC's responsibility to make the arrival report."),
  Q("notification-of-arrival", "'Booking out' means:", ["Informing the ATSU/aerodrome authority of your intended departure and flight details", "Paying the landing fee", "Filing a NOTAM", "Requesting a radar service"], 0, "Booking out = telling the aerodrome you're departing; booking in = telling them you've arrived."),
  Q("notification-of-arrival", "An aerodrome shown as PPR requires:", ["Prior permission from the aerodrome operator before arrival", "Prior payment of fees on arrival", "A professional pilot's licence", "Permission from customs"], 0, "PPR = Prior Permission Required."),

  Q("aerodrome-lighting", "Runway threshold lights are:", ["Green", "Red", "White", "Blue"], 0, "Green at the threshold as seen from the approach."),
  Q("aerodrome-lighting", "Runway end lights, as seen by an aircraft on the runway, are:", ["Red", "Green", "Yellow", "Blue"], 0, "Red marks the end of the runway."),
  Q("aerodrome-lighting", "Taxiway edge lights are:", ["Blue", "Green", "White", "Yellow"], 0, "Blue for boundaries; taxiway centreline lights are green."),
  Q("aerodrome-lighting", "Taxiway centreline lights are:", ["Green", "Blue", "White", "Red"], 0, "Green centreline; blue edges."),
  Q("aerodrome-lighting", "On a standard 4-light PAPI, you see two white and two red lights. You are:", ["On the correct glide path", "Slightly high", "Slightly low", "Well below the glide path"], 0, "2 white + 2 red = on slope (normally 3°)."),
  Q("aerodrome-lighting", "On a PAPI you see four red lights. You are:", ["Well below the glide path", "Well above the glide path", "On the glide path", "Slightly above the glide path"], 0, "All red = too low. All white = too high."),
  Q("aerodrome-lighting", "On a PAPI you see three white lights and one red light. You are:", ["Slightly above the glide path", "Slightly below the glide path", "On the glide path", "Far too low"], 0, "More white = higher. 3 white = slightly high."),
  Q("aerodrome-lighting", "An aerodrome identification beacon at a civil aerodrome flashes:", ["A two-letter Morse code identification in green", "A two-letter Morse code identification in red", "Alternate white and green", "Steady white"], 0, "Civil = green Morse; military = red."),
  Q("aerodrome-lighting", "You reach a lit red stop bar across a taxiway and ATC has cleared you onto the runway. You should:", ["Hold and query ATC — do not cross a lit stop bar", "Proceed, because you have a clearance", "Cross slowly", "Flash your landing light and proceed"], 0, "Never cross a lit red stop bar; ask ATC to switch it off."),
  Q("aerodrome-lighting", "Pairs of alternately flashing yellow lights at a taxiway holding position are:", ["Runway guard lights — warning that you are about to enter a runway", "Obstacle lights", "Taxiway edge lights", "Apron floodlights"], 0, "Runway guard lights (wig-wags) warn of the runway ahead."),
  Q("aerodrome-lighting", "Runway centreline lighting in the last 300 m of the runway is:", ["Red", "White", "Alternating red and white", "Green"], 0, "Alternating red/white from 900 m to 300 m remaining, then red for the last 300 m."),

  Q("light-signals", "A steady green light directed at an aircraft in flight means:", ["Cleared to land", "Return for landing", "Cleared to taxi", "Give way and continue circling"], 0, "Steady green in the air = cleared to land."),
  Q("light-signals", "A steady red light directed at an aircraft in flight means:", ["Give way to other aircraft and continue circling", "Aerodrome unsafe, do not land", "Land and proceed to the apron", "Cleared to land"], 0, "Steady red in the air = give way & keep circling. Flashing red = don't land."),
  Q("light-signals", "A series of green flashes directed at an aircraft in flight means:", ["Return for landing", "Cleared to land", "Cleared to taxi", "Do not land"], 0, "Green flashes in the air = come back to land (a steady green will follow)."),
  Q("light-signals", "A series of red flashes directed at an aircraft in flight means:", ["Aerodrome unsafe — do not land", "Give way and continue circling", "Return to the starting point", "Land immediately"], 0, "Red flashes in the air = aerodrome unsafe, don't land."),
  Q("light-signals", "A series of white flashes directed at an aircraft in flight means:", ["Land at this aerodrome and proceed to the apron", "Return to starting point", "Aerodrome unsafe", "Cleared to land on the grass"], 0, "White flashes in the air = land here and go to the apron."),
  Q("light-signals", "A red pyrotechnic light fired from the tower at an aircraft in flight means:", ["Notwithstanding any previous instructions, do not land for the time being", "Cleared to land", "Return to the starting point", "The aerodrome is closed permanently"], 0, "Red flare from the ground = don't land for now, whatever you were told before."),
  Q("light-signals", "A steady green light directed at an aircraft on the ground means:", ["Cleared for take-off", "Cleared to taxi", "Return to starting point", "Stop"], 0, "Steady green on the ground = cleared for take-off."),
  Q("light-signals", "A series of green flashes directed at an aircraft on the ground means:", ["Cleared to taxi", "Cleared for take-off", "Taxi clear of the landing area", "Stop"], 0, "Green flashes on the ground = cleared to taxi."),
  Q("light-signals", "A series of red flashes directed at an aircraft on the ground means:", ["Taxi clear of the landing area in use", "Stop", "Return to starting point", "Cleared for take-off"], 0, "Red flashes on the ground = get off the landing area."),
  Q("light-signals", "A series of white flashes directed at an aircraft on the ground means:", ["Return to the starting point on the aerodrome", "Cleared to taxi", "Taxi to the apron", "Stop immediately"], 0, "White flashes on the ground = return to the starting point."),
  Q("light-signals", "A steady red light directed at an aircraft on the ground means:", ["Stop", "Taxi clear of the landing area", "Return to starting point", "Give way to landing traffic"], 0, "Steady red on the ground = stop."),
  Q("light-signals", "By day, in flight, a pilot acknowledges a light signal by:", ["Rocking the wings (except on base and final)", "Flashing the landing lights twice", "Moving the ailerons", "Switching the navigation lights on and off"], 0, "Rock the wings — but not on base leg or final."),
  Q("light-signals", "At night, in flight, a pilot acknowledges a light signal by:", ["Flashing the landing lights twice (or nav lights twice if no landing lights)", "Rocking the wings", "Moving the rudder", "Firing a green flare"], 0, "Flash landing lights twice."),
  Q("light-signals", "By day, on the ground, a pilot acknowledges a light signal by:", ["Moving the ailerons or rudder", "Rocking the wings", "Flashing the landing lights twice", "Opening the canopy"], 0, "Move the ailerons or rudder."),
  Q("light-signals", "An aircraft repeatedly switching its landing lights on and off is signalling:", ["It has difficulties which compel it to land, but doesn't require immediate assistance", "It requires immediate assistance", "It acknowledges a light signal", "It is cleared to land"], 0, "That's an urgency signal. A red flare from an aircraft = distress."),

  Q("declared-distances", "TORA is defined as:", ["The length of runway declared available and suitable for the ground run of an aeroplane taking off", "The runway length plus clearway", "The runway length plus stopway", "The runway length available for landing"], 0, "TORA = take-off run available (the ground run)."),
  Q("declared-distances", "TODA is:", ["TORA plus clearway", "TORA plus stopway", "TORA minus any displaced threshold", "TORA plus stopway plus clearway"], 0, "Clearway is added for the airborne part of the take-off."),
  Q("declared-distances", "ASDA (EDA in the UK) is:", ["TORA plus stopway", "TORA plus clearway", "LDA plus stopway", "TODA minus clearway plus stopway"], 0, "Accelerate-stop: TORA + stopway."),
  Q("declared-distances", "A displaced threshold will normally reduce:", ["The LDA", "The TORA", "The TODA", "The ASDA"], 0, "The displaced section is usable for take-off, so only the landing distance is reduced."),
  Q("declared-distances", "A runway is 900 m long with a 60 m stopway and a 200 m clearway. The TODA and ASDA are:", ["TODA 1100 m, ASDA 960 m", "TODA 960 m, ASDA 1100 m", "TODA 1160 m, ASDA 1160 m", "TODA 900 m, ASDA 900 m"], 0, "TODA = 900 + 200 = 1100 m; ASDA = 900 + 60 = 960 m."),
  Q("declared-distances", "A runway is 800 m long with the landing threshold displaced by 150 m. The TORA and LDA are:", ["TORA 800 m, LDA 650 m", "TORA 650 m, LDA 800 m", "TORA 650 m, LDA 650 m", "TORA 950 m, LDA 800 m"], 0, "TORA is the full runway; LDA starts at the displaced threshold: 800 − 150 = 650 m."),
  Q("declared-distances", "A stopway is:", ["A prepared area beyond the end of the TORA able to support an aircraft during an abandoned take-off", "An obstacle-free area for the initial climb", "The area before a displaced threshold", "A holding area beside the runway"], 0, "Stopway must bear the aircraft's weight; clearway need not."),
  Q("declared-distances", "A clearway is:", ["A defined area beyond the end of the TORA, free of obstacles and under the aerodrome's control, over which an aeroplane may make part of its initial climb", "A paved area able to support an aircraft during an abandoned take-off", "A taxiway that is clear of traffic", "The part of the runway before the threshold"], 0, "Clearway = obstacle-free climb-out area."),

  Q("ground-right-of-way", "Two aircraft are taxiing head-on towards each other. They should:", ["Both stop or, where practicable, alter course to the right", "Both alter course to the left", "The one on the right gives way", "The heavier aircraft has right of way"], 0, "Head-on on the ground: stop or turn right."),
  Q("ground-right-of-way", "Two aircraft are taxiing on converging courses. Which gives way?", ["The one that has the other on its right", "The one that has the other on its left", "The larger aircraft", "The one nearest the runway"], 0, "Same as in the air: give way to the aircraft on your right."),
  Q("ground-right-of-way", "When one taxiing aircraft is overtaking another:", ["The aircraft being overtaken has right of way and the overtaking aircraft keeps well clear", "The overtaking aircraft has right of way", "Both must stop", "The overtaken aircraft must move to the left"], 0, "The overtaken aircraft has priority."),
  Q("ground-right-of-way", "An aircraft taxiing on the manoeuvring area must give way to:", ["Aircraft taking off, about to take off, or landing", "Vehicles towing aircraft", "All vehicles", "Only aircraft on its right"], 0, "Taxiing aircraft give way to those taking off or landing."),
  Q("ground-right-of-way", "In the UK, vehicles that are NOT towing aircraft must give way to:", ["Aircraft and vehicles towing aircraft", "Only aircraft taking off", "Nothing — vehicles have priority", "Only emergency vehicles"], 0, "Order: aircraft taking off/landing → taxiing aircraft → vehicles towing aircraft → other vehicles."),
  Q("ground-right-of-way", "At a runway-holding position, without further clearance, you must:", ["Stop and hold", "Proceed with caution if the runway looks clear", "Line up but not take off", "Cross if no aircraft is on final"], 0, "Stop and hold at all runway-holding positions unless cleared further."),

  Q("airfield-signage", "A sign with white characters on a red background is a:", ["Mandatory instruction sign", "Location sign", "Direction sign", "Information sign"], 0, "Red = mandatory."),
  Q("airfield-signage", "A sign with yellow characters on a black background, with a yellow border, is a:", ["Location sign — it shows the taxiway you are on", "Direction sign", "Mandatory instruction sign", "Distance remaining sign"], 0, "Black location sign = 'you are here'."),
  Q("airfield-signage", "A sign with black characters and an arrow on a yellow background is a:", ["Direction sign", "Location sign", "Mandatory sign", "NO ENTRY sign"], 0, "Yellow signs give directions/information."),
  Q("airfield-signage", "A sign reading '09-27' in white on red, beside a taxiway, indicates:", ["A runway-holding position for runway 09/27 — do not proceed without clearance", "Directions to runway 09/27", "You are on runway 09/27", "Runway 09/27 is closed"], 0, "It is a mandatory runway designation sign at the holding position."),
  Q("airfield-signage", "A red sign showing a white circle with a horizontal bar means:", ["No entry", "Stop and hold", "Runway ahead", "One-way taxiway"], 0, "That's the NO ENTRY mandatory sign."),
  Q("airfield-signage", "A runway-vacated sign (holding marking symbol in black on yellow) is seen:", ["When leaving the runway — beyond it you are clear of the runway/ILS sensitive area", "Before entering the runway", "At the end of the runway", "At the apron entrance"], 0, "It tells you that you have vacated the runway area."),

  Q("aerodrome-markings", "A runway designator '27' indicates that the runway direction is approximately:", ["270° magnetic", "270° true", "027° magnetic", "270° grid"], 0, "Designators use magnetic direction ÷ 10, rounded."),
  Q("aerodrome-markings", "White arrows on the runway centreline leading to a white threshold bar indicate:", ["A displaced threshold — the area may be used for taxiing and take-off but not for landing", "An area unusable for any movement", "A taxiway crossing", "A stopway"], 0, "Arrows = displaced threshold; you mustn't touch down before the bar."),
  Q("aerodrome-markings", "Yellow chevrons before the start of a runway indicate:", ["A pre-threshold area not usable for normal movement of aircraft", "A displaced threshold usable for take-off", "A runway-holding position", "A closed taxiway"], 0, "Chevrons mark blast pads/stopways — not for normal taxi, take-off or landing."),
  Q("aerodrome-markings", "At a Pattern A runway-holding position (two solid and two dashed lines), an aircraft approaching the runway should stop:", ["At the solid lines, on the side away from the runway", "At the dashed lines", "Between the solid and dashed lines", "Only if the sign is lit"], 0, "Solid = stop. The dashed side faces the runway."),
  Q("aerodrome-markings", "A 'ladder' pattern holding position (Pattern B) is used:", ["As an ILS / CAT II/III holding position", "At intermediate taxiway intersections", "To mark a closed taxiway", "At the end of a stopway"], 0, "Pattern B protects the ILS sensitive area."),
  Q("aerodrome-markings", "A white cross on a runway indicates:", ["The runway, or that part of it, is closed", "A runway intersection", "A helicopter landing area", "The aiming point"], 0, "White X on a runway = closed; yellow X on a taxiway = closed."),
  Q("aerodrome-markings", "Taxiway centreline markings are:", ["Yellow", "White", "Blue", "Orange"], 0, "Taxiway markings are yellow; runway markings white."),
  Q("aerodrome-markings", "The number of longitudinal stripes in runway threshold markings indicates:", ["The runway width", "The runway length", "The runway's strength", "The approach category"], 0, "More stripes = wider runway (e.g. 8 stripes for 30 m)."),
  Q("aerodrome-markings", "A single dashed yellow line across a taxiway is a:", ["Intermediate holding position marking", "Runway-holding position marking", "Taxiway edge marking", "Closed taxiway marking"], 0, "Intermediate holding positions use a single dashed line."),

  Q("aircraft-log-books", "Which log books are required for a single-engine aeroplane with a variable-pitch propeller?", ["Aircraft log book, engine log book and variable-pitch propeller log book", "Aircraft log book only", "Aircraft and engine log books only", "Pilot's log book and technical log only"], 0, "Separate logs for airframe, each engine and each VP propeller."),
  Q("aircraft-log-books", "Aircraft log books must be preserved until:", ["2 years after the aircraft has been destroyed or permanently withdrawn from use", "6 months after the next weighing", "2 years after the last entry", "The aircraft is sold"], 0, "2 years after destruction/permanent withdrawal."),
  Q("aircraft-log-books", "Who is responsible for keeping the aircraft log books?", ["The operator/owner of the aircraft", "The pilot-in-command", "The CAA", "The maintenance organisation only"], 0, "The operator keeps the aircraft's records."),
  Q("aircraft-log-books", "Entries in an aircraft log book should be made:", ["As soon as practicable after the event to which they relate", "Only at the annual inspection", "Within 2 years", "Only when the aircraft is sold"], 0, "Entries must be made promptly after the occurrence."),
  Q("aircraft-log-books", "Before an aircraft flies after maintenance, it requires:", ["A Certificate of Release to Service", "A new C of A", "A new weight schedule", "A new Certificate of Registration"], 0, "A CRS certifies that the maintenance was completed correctly."),

  Q("weight-schedules", "A weight schedule must be preserved until:", ["6 months after the next occasion on which the aircraft is weighed", "2 years after the aircraft is withdrawn from use", "The next annual inspection", "12 months after issue"], 0, "6 months after the NEXT weighing."),
  Q("weight-schedules", "The weight schedule gives:", ["The basic weight of the aircraft and the position of its centre of gravity at that weight", "The maximum take-off weight only", "The weight of the crew and passengers", "The fuel load for each flight"], 0, "Basic weight + CG at basic weight (plus the list of basic equipment)."),
  Q("weight-schedules", "The basic weight of a light aircraft normally includes:", ["The aircraft, its basic equipment, and unusable fuel and oil", "The aircraft plus full fuel", "The aircraft, crew and full fuel", "The aircraft plus pilot only"], 0, "Basic weight includes unusable fuel/oil but not usable fuel or payload."),
  Q("weight-schedules", "Who must keep the weight schedule?", ["The operator", "The pilot-in-command", "The aerodrome operator", "The CAA"], 0, "The operator keeps it and makes it available."),

  Q("night-navigation-lights", "An aircraft's navigation lights are:", ["Red on the left wingtip, green on the right wingtip, white at the tail", "Green on the left, red on the right, white at the tail", "Red on the left, green on the right, red at the tail", "White on both wings, red at the tail"], 0, "Port (left) = red; starboard (right) = green; tail = white."),
  Q("night-navigation-lights", "The red and green navigation lights each show through an arc of:", ["110° from dead ahead", "70° from dead ahead", "140° from dead ahead", "90° from dead ahead"], 0, "Red and green: 110° each. White tail: 140°."),
  Q("night-navigation-lights", "The white tail light shows through an arc of:", ["140° (70° either side of dead astern)", "110°", "180°", "70°"], 0, "70° each side of the tail = 140°."),
  Q("night-navigation-lights", "At night you see another aircraft's red light, on a constant bearing, out to your right at the same level. You should:", ["Give way — normally by turning right to pass behind it", "Maintain heading and speed — it must give way", "Turn left to pass in front", "Climb immediately"], 0, "Red seen on your right: it's converging from your right, so you give way."),
  Q("night-navigation-lights", "At night you see only a white light ahead of you, getting closer. You are:", ["Overtaking another aircraft — keep clear by altering heading to the right", "Head-on with another aircraft", "Being overtaken", "Converging from the left"], 0, "Only the white tail light = you're behind it; you're the overtaking aircraft."),
  Q("night-navigation-lights", "At night you see both a red and a green light from another aircraft, directly ahead. You should:", ["Alter heading to the right — it's head-on", "Alter heading to the left", "Maintain heading — it will give way", "Descend"], 0, "Red + green together = head-on. Both turn right."),
  Q("night-navigation-lights", "Navigation lights must be displayed:", ["Between sunset and sunrise", "Only in IMC", "From 30 minutes after sunset to 30 minutes before sunrise only", "Only in controlled airspace"], 0, "SERA: sunset to sunrise (UK 'night' for licensing is 30 min after sunset to 30 min before sunrise)."),
  Q("night-navigation-lights", "In the UK, 'night' (for licensing and logging) is:", ["From 30 minutes after sunset until 30 minutes before sunrise", "From sunset until sunrise", "From 1 hour after sunset until 1 hour before sunrise", "When the sun is 6° below the horizon"], 0, "UK ANO defines night as sunset + 30 min to sunrise − 30 min."),
  Q("night-navigation-lights", "The purpose of anti-collision lights is to:", ["Attract attention to the aircraft", "Show the aircraft's direction of travel", "Illuminate the runway", "Signal an emergency"], 0, "Flashing red/white anti-collision lights make the aircraft conspicuous."),

  Q("in-flight-right-of-way", "Two power-driven aircraft are approaching head-on at the same level. They should:", ["Each alter heading to the right", "Each alter heading to the left", "The one on the right maintains heading", "The higher aircraft climbs"], 0, "Head-on: both turn right."),
  Q("in-flight-right-of-way", "Two power-driven aeroplanes are converging at about the same level. Which gives way?", ["The one that has the other on its right", "The one that has the other on its left", "The faster one", "The higher one"], 0, "Give way to the aircraft on your right."),
  Q("in-flight-right-of-way", "A powered aeroplane is converging with a glider that is on the aeroplane's LEFT. Who gives way?", ["The powered aeroplane", "The glider", "Both turn right", "Neither — the glider maintains course"], 0, "Category hierarchy beats the 'on your right' rule: powered gives way to gliders."),
  Q("in-flight-right-of-way", "A glider and a balloon are converging. Who gives way?", ["The glider", "The balloon", "Both turn right", "The one on the left"], 0, "Gliders give way to balloons."),
  Q("in-flight-right-of-way", "An airship and a glider are converging. Who gives way?", ["The airship", "The glider", "The one with the other on its right", "Both climb"], 0, "Airships give way to gliders and balloons."),
  Q("in-flight-right-of-way", "A power-driven aircraft is converging with an aircraft seen to be towing a glider. Who gives way?", ["The power-driven aircraft that is not towing", "The towing aircraft", "Whichever is on the right", "The glider must release"], 0, "Power-driven aircraft give way to aircraft seen towing other aircraft or objects."),
  Q("in-flight-right-of-way", "An aeroplane overtaking another aeroplane should:", ["Keep out of the way by altering heading to the right", "Alter heading to the left", "Climb above the other aircraft", "Pass underneath"], 0, "The overtaking aircraft alters to the right and stays clear until past."),
  Q("in-flight-right-of-way", "In the UK, a glider overtaking another glider:", ["May alter heading to the left or to the right", "Must alter heading to the right", "Must alter heading to the left", "Must climb above it"], 0, "UK Rules of the Air allow gliders overtaking gliders to go either way."),
  Q("in-flight-right-of-way", "Two aeroplanes are approaching an aerodrome to land. Which has right of way?", ["The lower one — but it must not cut in front of an aircraft on final", "The higher one", "The faster one", "The one on the right"], 0, "Higher gives way to lower."),
  Q("in-flight-right-of-way", "The aircraft that has the right of way should:", ["Maintain its heading and speed", "Climb to show it has seen the other", "Turn right", "Slow down"], 0, "Stand-on aircraft maintains heading and speed (while staying vigilant)."),
  Q("in-flight-right-of-way", "An aircraft is 'overtaking' when it approaches another from behind within:", ["70° of the other aircraft's plane of symmetry", "110° of its plane of symmetry", "45° of its plane of symmetry", "90° of its plane of symmetry"], 0, "Within 70° either side of the tail — the white light arc."),
  Q("in-flight-right-of-way", "Under the UK right-hand traffic rule, an aircraft following a railway line should keep it:", ["On its left", "On its right", "Directly beneath", "At least 1 km away"], 0, "Keep the line feature on your left, so you're on the right of it."),
  Q("in-flight-right-of-way", "You become aware that another aircraft is compelled to land. You must:", ["Give way to it", "Maintain heading if it is on your left", "Land first", "Follow it down"], 0, "Give way to an aircraft known to be compelled to land."),

  Q("certificate-of-airworthiness", "An Airworthiness Review Certificate (ARC) is normally valid for:", ["12 months", "6 months", "2 years", "3 years"], 0, "The ARC is renewed annually."),
  Q("certificate-of-airworthiness", "Which would make an aircraft's C of A invalid?", ["An unapproved modification has been made", "The pilot's medical has expired", "The weight schedule is 6 months old", "The aircraft has changed hangar"], 0, "Unapproved modifications/repairs, missed maintenance, or flying outside the flight manual limits invalidate the C of A."),
  Q("certificate-of-airworthiness", "A UK-registered aircraft that does not qualify for a C of A may be flown with:", ["A Permit to Fly", "An ARC only", "A Certificate of Registration only", "A noise certificate"], 0, "Permit to Fly (e.g. LAA homebuilts)."),
  Q("certificate-of-airworthiness", "The C of A for a G-registered aircraft is issued by:", ["The UK CAA", "The aircraft manufacturer", "The aircraft owner", "ICAO"], 0, "Issued by the State of Registry — the CAA."),
  Q("certificate-of-airworthiness", "For a flight that takes off and lands at the same aerodrome, the aircraft documents (e.g. C of A, C of R):", ["May be kept at that aerodrome instead of being carried", "Must always be carried on board", "Are not required", "Must be posted to the CAA"], 0, "Part-NCO allows documents to be retained at the aerodrome for A-to-A flights."),
  Q("certificate-of-airworthiness", "The flight manual's operating limitations:", ["Must be complied with — operating outside them breaches the conditions of the C of A", "Are advisory only", "Apply only to commercial flights", "Apply only to the first 100 hours"], 0, "The flight manual limitations are binding."),

  Q("crew-log-books", "A pilot's personal flying log book must be preserved for at least:", ["2 years after the date of the last entry", "6 months after the last flight", "2 years after the licence is issued", "5 years after the first entry"], 0, "2 years after the last entry."),
  Q("crew-log-books", "For an aeroplane, 'flight time' is measured from:", ["The moment it first moves for the purpose of taking off until it finally comes to rest at the end of the flight", "Wheels off to wheels on", "Engine start to engine shutdown", "Take-off clearance to landing"], 0, "Chocks off to chocks on, effectively."),
  Q("crew-log-books", "Which of these is NOT required to be recorded in a pilot's log book?", ["The fuel uplift", "The aircraft type and registration", "The place and time of departure and arrival", "The capacity in which the pilot acted"], 0, "Fuel isn't a pilot logbook requirement; date, places, times, type/reg, capacity and flight time are."),
  Q("crew-log-books", "Your personal log book must contain your:", ["Name and address", "Medical history", "Bank details", "Aircraft insurance policy number"], 0, "The holder's name and address are recorded."),

  Q("poh", "Which section of a POH contains the approved limitations?", ["Section 2", "Section 1", "Section 4", "Section 7"], 0, "Section 2 — Limitations (approved)."),
  Q("poh", "Take-off and landing distance information is found in which section of the POH?", ["Section 5 — Performance", "Section 2 — Limitations", "Section 4 — Normal Procedures", "Section 6 — Weight & Balance"], 0, "Performance is Section 5."),
  Q("poh", "On an airspeed indicator, the white arc runs from:", ["VSO to VFE", "VS1 to VNO", "VNO to VNE", "VS1 to VFE"], 0, "White = flap operating range."),
  Q("poh", "On an airspeed indicator, the green arc runs from:", ["VS1 to VNO", "VSO to VFE", "VNO to VNE", "VSO to VNO"], 0, "Green = normal operating range."),
  Q("poh", "The yellow arc on an airspeed indicator indicates:", ["The caution range — operate only in smooth air (VNO to VNE)", "The flap operating range", "The normal operating range", "The best glide speed range"], 0, "Yellow = caution, smooth air only."),
  Q("poh", "The red line on an airspeed indicator marks:", ["VNE — never exceed speed", "VNO — max structural cruising speed", "VFE — max flap extended speed", "VA — manoeuvring speed"], 0, "Red line = VNE."),
  Q("poh", "Emergency procedures are in which section of the POH?", ["Section 3", "Section 2", "Section 5", "Section 9"], 0, "Section 3 — Emergency Procedures."),

  Q("low-flying", "Except for take-off and landing, an aircraft must not fly over a congested area below:", ["1000 ft above the highest obstacle within 600 m of the aircraft", "500 ft above the highest obstacle within 150 m", "1500 ft above ground level", "1000 ft above the highest obstacle within 8 km"], 0, "SERA.5005(f)(1): 1000 ft / 600 m."),
  Q("low-flying", "In the UK, outside congested areas, an aircraft must not be flown closer than 500 ft to:", ["Any person, vessel, vehicle or structure", "The ground", "Any controlled airspace boundary", "Any aerodrome"], 0, "The UK applies a 500 ft distance 'bubble' instead of the SERA 500 ft height rule."),
  Q("low-flying", "Over a congested area, as well as the 1000 ft rule, you must be at a height that:", ["Would allow you to land clear without undue hazard to people or property if an engine failed", "Keeps you above all cloud", "Is at least 2000 ft AGL", "Keeps you in radio contact"], 0, "You must be able to glide clear of the built-up area."),
  Q("low-flying", "The low-flying minima do not apply when:", ["Taking off or landing in accordance with normal aviation practice", "Flying a single-engine aircraft", "Flying below cloud", "Flying on a Sunday"], 0, "Take-off and landing are excepted."),
  Q("low-flying", "For a VFR flight at night, the minimum height (except for take-off and landing) is:", ["1000 ft above the highest obstacle within 8 km of the estimated position", "500 ft above the highest obstacle within 150 m", "1500 ft AGL", "2000 ft above the highest obstacle within 5 nm"], 0, "Night VFR: 1000 ft / 8 km."),
  Q("low-flying", "You are flying over open countryside at 400 ft AGL. A farmer on a tractor is 300 ft from your aircraft. Under UK rules this is:", ["Illegal — you are closer than 500 ft to a person/vehicle", "Legal — you are above 300 ft", "Legal — the rule only applies to buildings", "Legal — open countryside has no minimum"], 0, "The 500 ft bubble applies to persons and vehicles."),
  Q("low-flying", "The congested-area rule uses a radius of:", ["600 metres", "600 feet", "150 metres", "1000 metres"], 0, "1000 FEET above the highest obstacle within 600 METRES."),

  Q("collision-avoidance", "Who has ultimate responsibility for avoiding a collision?", ["The pilot-in-command", "ATC", "The aircraft with right of way", "The aircraft on the left"], 0, "The PIC is never relieved of collision avoidance responsibility."),
  Q("collision-avoidance", "Vigilance for the purpose of detecting potential collisions:", ["Must not be relaxed regardless of the type of flight or class of airspace", "May be relaxed in controlled airspace", "Is ATC's responsibility under a radar service", "Is only required in Class G airspace"], 0, "SERA.3210(a)."),
  Q("collision-avoidance", "Another aircraft remains in the same position on your windscreen while getting larger. This indicates:", ["A collision course", "It is moving away", "It is passing safely behind you", "It is overtaking you"], 0, "Constant relative bearing + decreasing range = collision course."),
  Q("collision-avoidance", "An effective lookout scan uses:", ["Sectors of about 10–15° with a pause of about 1 second in each", "Continuous rapid sweeping of the horizon", "Looking straight ahead only", "One 360° look every 10 minutes"], 0, "Short pauses let the eyes focus and detect movement."),
  Q("collision-avoidance", "You are flying VFR with an ATC clearance in a Class D zone. Responsibility for avoiding other VFR traffic lies with:", ["You, the pilot-in-command", "ATC", "The aircraft with the higher priority", "The aerodrome operator"], 0, "ATC don't separate VFR from VFR in Class D — they give traffic information; you see and avoid."),
  Q("collision-avoidance", "The aircraft with right of way sees that the give-way aircraft hasn't taken action and a collision is likely. It should:", ["Take whatever action best avoids a collision", "Maintain heading and speed regardless", "Turn left", "Report the other pilot to ATC first"], 0, "Right of way never removes the duty to avoid a collision."),
  Q("aics", "An Aeronautical Information Circular (AIC) is used to publish:", ["Information that does not qualify for inclusion in the AIP or a NOTAM, such as advance notice of changes and advisory material", "All permanent changes to aerodrome data", "Short-notice closures of aerodromes", "Weather forecasts"], 0, "AICs cover what doesn't belong in the AIP (permanent) or a NOTAM (temporary/short-notice)."),
  Q("aics", "A pink AIC deals with:", ["Safety-related topics", "Administrative matters", "Operational matters including ATS", "Maps and charts"], 0, "Pink = safety."),
  Q("aics", "A yellow AIC deals with:", ["Operational matters, including ATS facilities and requirements", "Safety-related topics", "Airspace restrictions", "Administrative matters"], 0, "Yellow = operational."),
  Q("aics", "A mauve AIC deals with:", ["UK airspace restrictions", "Maps and charts", "Administrative matters", "Safety-related topics"], 0, "Mauve = airspace restrictions (e.g. temporary restricted areas)."),
  Q("aics", "A white AIC deals with:", ["Administrative matters", "Safety-related topics", "Operational matters", "Airspace restrictions"], 0, "White = administrative (e.g. charges, exam dates)."),
  Q("aics", "Green AICs contain:", ["Maps and charts", "Safety information", "Airspace restrictions", "Licensing administration"], 0, "Green = maps/charts."),
  Q("aics", "Permanent aeronautical information, such as aerodrome data, is published in the:", ["AIP", "AIC", "NOTAM", "Pre-flight Information Bulletin only"], 0, "The AIP holds permanent information (GEN, ENR, AD)."),

  Q("chicago-search", "Under the Chicago Convention, the authorities of a state may search a foreign aircraft:", ["On landing or departure, without unreasonable delay", "At any time while it is in that state's airspace", "Only with permission of the state of registration", "Only if a crime is suspected"], 0, "Article 16: on landing or departure, without unreasonable delay."),
  Q("chicago-search", "Which Article of the Chicago Convention gives states the right to search aircraft and inspect their documents?", ["Article 16", "Article 1", "Article 24", "Article 29"], 0, "Article 16 — search of aircraft."),
  Q("chicago-search", "When a state's authorities search a foreign aircraft, they may inspect:", ["The certificates and other documents prescribed by the Convention", "Only the pilot's licence", "Only the cargo manifest", "Nothing — only the aircraft itself"], 0, "They may inspect the certificates and documents prescribed by the Convention."),
  Q("chicago-search", "A state's laws on admission to, departure from and operation within its territory apply:", ["To aircraft of all contracting states, without distinction of nationality", "Only to aircraft registered in that state", "Only to scheduled airlines", "Only to military aircraft"], 0, "Article 11 — applicability of air regulations."),

  Q("chicago-customs-duty", "Under Article 24, fuel and lubricating oil on board a foreign aircraft on arrival are exempt from customs duty provided they are:", ["Retained on board", "Declared to customs", "Used within 24 hours", "Less than 100 litres"], 0, "The exemption applies to items retained on board."),
  Q("chicago-customs-duty", "Which of these is covered by the Article 24 customs duty exemption?", ["Spare parts, regular equipment and aircraft stores retained on board", "Passengers' duty-free purchases", "Cargo being delivered", "Anything the crew unloads"], 0, "Fuel, oil, spares, regular equipment and stores retained on board are exempt."),
  Q("chicago-customs-duty", "Fuel that is unloaded from a foreign aircraft at an airport:", ["Is not normally covered by the exemption (except under customs regulations)", "Is always duty-free", "Must be returned to the aircraft", "Is confiscated"], 0, "The exemption doesn't apply to quantities unloaded, except as customs regulations allow."),
  Q("chicago-customs-duty", "An aircraft on a flight to, from or across another contracting state is:", ["Admitted temporarily free of duty, subject to that state's customs regulations", "Charged import duty on arrival", "Required to pay a transit fee", "Impounded until customs clearance"], 0, "Article 24: temporary admission free of duty."),

  Q("chicago-rules-of-air", "A UK-registered aircraft flying over France must comply with:", ["The rules of the air in force in France", "UK rules only", "ICAO Annex 2 only", "Whichever rules the pilot chooses"], 0, "Article 12: comply with the rules of the state being flown over."),
  Q("chicago-rules-of-air", "Over the high seas, the rules of the air in force are:", ["Those established under the Chicago Convention (ICAO Annex 2)", "Those of the state of registration", "Those of the nearest state", "None"], 0, "Over the high seas, Annex 2 applies without national deviation."),
  Q("chicago-rules-of-air", "Which Article of the Chicago Convention deals with the rules of the air?", ["Article 12", "Article 16", "Article 5", "Article 30"], 0, "Article 12 — rules of the air."),
  Q("chicago-rules-of-air", "Under Article 12, each contracting state undertakes to:", ["Ensure the prosecution of all persons violating the regulations", "Pay for search and rescue", "Accept all foreign licences without question", "Allow scheduled services without permission"], 0, "States undertake to prosecute violators."),

  Q("radio-licensing", "In the UK, the aircraft radio station licence is issued by:", ["Ofcom", "The CAA", "NATS", "ICAO"], 0, "Ofcom licenses the equipment; the CAA licenses the operator (FRTOL)."),
  Q("radio-licensing", "The Flight Radiotelephony Operator's Licence (FRTOL) is issued by:", ["The CAA", "Ofcom", "The aircraft operator", "Border Force"], 0, "The FRTOL is a CAA licence."),
  Q("radio-licensing", "Under Article 30, a licence to install and operate radio transmitting apparatus in an aircraft is issued by:", ["The state of registration", "The state being flown over", "ICAO", "The manufacturer"], 0, "The state of registration licenses the radio."),
  Q("radio-licensing", "When an aircraft uses its radio in the territory of another state, it must do so:", ["In accordance with the regulations of that state", "In accordance with the state of registration only", "Only in emergencies", "Only on 121.5 MHz"], 0, "Article 30: use radio in accordance with the regulations of the state flown over."),
  Q("radio-licensing", "Radio transmitting apparatus in an aircraft may be used only by:", ["Members of the flight crew holding a licence for the purpose issued by the state of registration", "Any passenger", "Anyone over 16", "Only the aircraft owner"], 0, "Article 30: flight crew holding a special licence."),

  Q("chicago-customs-airports", "An aircraft entering a contracting state must normally land at:", ["An airport designated by that state for customs and other examination", "Any aerodrome", "The nearest military airfield", "The capital city's main airport"], 0, "Article 10 — land at a designated customs airport."),
  Q("chicago-customs-airports", "An aircraft departing from a contracting state on an international flight must normally depart from:", ["A designated customs airport", "Any licensed aerodrome", "An airport in the state of registration", "Any airstrip with fuel"], 0, "Article 10 covers departure as well as arrival."),
  Q("chicago-customs-airports", "Which Article of the Chicago Convention requires landing at customs airports?", ["Article 10", "Article 5", "Article 24", "Article 1"], 0, "Article 10 — landing at customs airport."),
  Q("chicago-customs-airports", "The rules on immigration, passports, customs and quarantine for passengers, crew and cargo are covered by:", ["Article 13 — entry and clearance regulations", "Article 1 — sovereignty", "Article 30 — radio", "Article 12 — rules of the air"], 0, "Article 13 — entry and clearance."),

  Q("international-documents", "Which of these is NOT one of the documents required by Article 29 for international flight?", ["The pilot's personal flying log book", "Certificate of Registration", "Certificate of Airworthiness", "Journey log book"], 0, "Article 29 requires crew licences, not personal log books."),
  Q("international-documents", "Under Article 29, which documents must always be carried?", ["Certificate of Registration, Certificate of Airworthiness, crew licences and journey log book", "Only the crew licences", "Certificate of Registration and insurance only", "The weight schedule and POH"], 0, "Those four are always required; radio licence, passenger list and cargo manifest are conditional."),
  Q("international-documents", "The aircraft radio station licence must be carried on an international flight:", ["If the aircraft is equipped with radio apparatus", "Always", "Only on scheduled flights", "Only over the high seas"], 0, "It's conditional on having radio fitted."),
  Q("international-documents", "If an aircraft carries passengers on an international flight, Article 29 requires:", ["A list of their names and places of embarkation and destination", "Their passports to be held by the pilot", "A cargo manifest", "A separate passenger licence"], 0, "A passenger list is required when carrying passengers."),
  Q("international-documents", "A Certificate of Airworthiness for an aircraft in international navigation is issued or rendered valid by:", ["The state of registration", "The state being flown over", "The manufacturer", "ICAO"], 0, "Article 31."),
  Q("international-documents", "Certificates and licences issued by the state of registration are recognised by other states if:", ["They meet the minimum standards established under the Convention", "They are translated into English", "They are less than 1 year old", "The pilot has flown there before"], 0, "Article 33 — recognition of certificates and licences."),

  Q("chicago-non-scheduled", "A private aircraft from one contracting state on a non-scheduled flight may overfly another contracting state:", ["Without prior permission, subject to that state's right to require it to land", "Only with prior diplomatic clearance", "Only if it lands at a customs airport first", "Never"], 0, "Article 5 — right of non-scheduled flight."),
  Q("chicago-non-scheduled", "A 'stop for non-traffic purposes' means a stop:", ["For reasons such as refuelling or repairs, not to take on or put down passengers, cargo or mail", "To drop off passengers", "To collect cargo", "For sightseeing"], 0, "Non-traffic = technical stop."),
  Q("chicago-non-scheduled", "Scheduled international air services over or into a contracting state:", ["Require special permission or authorisation from that state", "Need no permission", "Need only ICAO approval", "Need only a flight plan"], 0, "Article 6 — scheduled services need permission."),
  Q("chicago-non-scheduled", "For safety, a state may require non-scheduled aircraft flying over regions that are inaccessible or lack adequate air navigation facilities to:", ["Follow prescribed routes or obtain special permission", "Fly at night only", "Carry a second pilot", "Fly above FL100"], 0, "Article 5 allows this safety restriction."),
  Q("chicago-non-scheduled", "Cabotage (carrying passengers for hire between two points within one state) by foreign aircraft:", ["May be refused by that state", "Is always allowed", "Is allowed for non-scheduled flights only", "Is prohibited by ICAO everywhere"], 0, "Article 7 — states may reserve cabotage."),

  Q("chicago-sovereignty", "Article 1 of the Chicago Convention states that every state has:", ["Complete and exclusive sovereignty over the airspace above its territory", "Sovereignty up to FL660", "Shared sovereignty with ICAO", "Sovereignty only over land"], 0, "Article 1 — complete and exclusive sovereignty."),
  Q("chicago-sovereignty", "For the purposes of the Chicago Convention, a state's territory includes:", ["Its land areas and adjacent territorial waters", "Its land areas only", "Its land and the high seas within 200 nm", "Only areas within its FIR"], 0, "Article 2 — land areas and territorial waters."),
  Q("chicago-sovereignty", "The Chicago Convention applies to:", ["Civil aircraft only", "Civil and military aircraft", "State aircraft only", "All aircraft including police and customs"], 0, "Article 3 — state aircraft (military, customs, police) are excluded."),
  Q("chicago-sovereignty", "An aircraft has the nationality of:", ["The state in which it is registered", "Its owner", "Its manufacturer", "The state it is flying over"], 0, "Article 17."),
  Q("chicago-sovereignty", "An aircraft may be validly registered in:", ["Only one state at a time", "Up to two states", "Any number of states", "Its owner's state and the manufacturer's state"], 0, "Article 18 — no dual registration."),

  Q("notams", "A NOTAM is used to give information that is:", ["Temporary or short-notice and essential to flight operations", "Permanent and non-urgent", "Only about weather", "Only about military flying"], 0, "NOTAMs carry timely, often temporary, information."),
  Q("notams", "Times in a NOTAM are given in:", ["UTC", "Local time", "BST in summer", "The time zone of the aerodrome"], 0, "NOTAM times are always UTC."),
  Q("notams", "In a NOTAM, item C) PERM means:", ["The NOTAM is permanent", "Permission is required", "The facility is permanently closed", "The item is performance-related"], 0, "PERM = permanent validity (the information will normally be added to the AIP)."),
  Q("notams", "In a NOTAM, item A) shows:", ["The ICAO location indicator of the aerodrome or FIR affected", "The start time", "The plain-language text", "The upper limit"], 0, "A) = location."),
  Q("notams", "In a NOTAM, item E) contains:", ["The plain-language (abbreviated) text of the notice", "The start of validity", "The lower limit", "The schedule"], 0, "E) = the actual message."),
  Q("notams", "The NOTAM code QMRLC means:", ["Runway closed", "Aerodrome closed", "Taxiway lighting unserviceable", "Restricted area activated"], 0, "MR = runway, LC = closed."),
  Q("notams", "Who is responsible for checking the NOTAMs relevant to a flight?", ["The pilot-in-command", "ATC at the departure aerodrome", "The aircraft owner", "The CAA"], 0, "SERA.2010(b): the PIC must become familiar with all available information."),
  Q("notams", "Significant permanent changes to the AIP take effect on common dates every:", ["28 days (AIRAC cycle)", "7 days", "3 months", "Year"], 0, "The AIRAC cycle runs on a 28-day schedule."),

  Q("crs", "After maintenance, an aircraft may not fly until:", ["A Certificate of Release to Service has been issued", "A new C of A has been issued", "The CAA has inspected it", "It has been re-weighed"], 0, "A CRS is needed after maintenance."),
  Q("crs", "A CRS certifies that:", ["The maintenance was carried out in accordance with the requirements and the aircraft is fit for release", "The aircraft is insured", "The pilot is fit to fly", "The aircraft has a valid ARC"], 0, "It certifies the work and release to service."),
  Q("crs", "A CRS is issued by:", ["Appropriately authorised certifying staff or an approved maintenance organisation", "Any pilot", "The aircraft's insurer", "ATC"], 0, "Only authorised persons/organisations (or a pilot-owner for permitted pilot-owner tasks)."),
  Q("crs", "Under Part-ML, a pilot-owner may:", ["Carry out permitted pilot-owner maintenance tasks and issue the CRS for them", "Carry out any maintenance and issue a CRS", "Issue an ARC", "Approve modifications"], 0, "Pilot-owners are limited to the defined pilot-owner tasks."),
  Q("crs", "You find the last maintenance entry in the tech log has no CRS signature. You should:", ["Not fly the aircraft until a CRS is issued", "Fly, as long as the work looks complete", "Sign it yourself", "Fly locally only"], 0, "No CRS = not released to service."),

  Q("preflight-docs", "Before flight, who must be satisfied that the aircraft is airworthy and its documents valid?", ["The pilot-in-command", "The aircraft owner only", "The flying club secretary", "ATC"], 0, "This is a PIC responsibility."),
  Q("preflight-docs", "The tech log shows 1247.3 hours. The next 50-hour check is due at 1248.0 hours. Your planned flight is 1.5 hours. You should:", ["Not fly as planned — the check would become overdue during the flight", "Fly, because the check isn't due yet", "Fly and report it afterwards", "Fly but stay in the circuit"], 0, "1247.3 + 1.5 = 1248.8 h, past the 1248.0 h limit."),
  Q("preflight-docs", "The aircraft's ARC expired yesterday. The aircraft:", ["Is not airworthy for flight — its C of A is not valid without a current ARC", "May fly for up to 30 days", "May fly locally only", "May fly if the C of A is in date"], 0, "The C of A is only valid with a current ARC."),
  Q("preflight-docs", "Where would you look to see if a previous pilot reported a defect?", ["The technical log / defect log", "The POH", "The weight schedule", "The C of R"], 0, "Defects are recorded in the tech log."),
  Q("preflight-docs", "Which of these would make an aircraft a 'no-go' before flight?", ["An unrectified defect affecting airworthiness with no approved deferral", "A torn seat cover", "A scratch on the spinner paint", "The previous pilot's fuel receipt missing"], 0, "Airworthiness defects must be fixed (or properly deferred) before flight."),

  Q("landing-right-of-way", "Two powered aeroplanes are approaching to land. Which has priority?", ["The lower one", "The higher one", "The faster one", "The one on the right"], 0, "The higher aircraft gives way to the lower."),
  Q("landing-right-of-way", "The lower of two aircraft approaching to land:", ["Must not take advantage of its priority to cut in front of or overtake an aircraft on final", "May cut in front of the other", "Must go around", "Must give way to the higher one"], 0, "Priority doesn't allow cutting in."),
  Q("landing-right-of-way", "A powered aeroplane and a glider are both approaching to land. The glider is higher. Who gives way?", ["The powered aeroplane", "The glider", "Whichever is on the left", "Both go around"], 0, "Power-driven aircraft give way to gliders, regardless of height."),
  Q("landing-right-of-way", "An aircraft in flight or operating on the ground must give way to:", ["Aircraft landing or in the final stages of an approach to land", "Aircraft on the downwind leg", "Aircraft holding at the runway", "Aircraft taxiing to the apron"], 0, "Landing aircraft have priority."),
  Q("landing-right-of-way", "You learn that another aircraft is compelled to land because of an engine problem. You must:", ["Give way to it", "Continue your approach if you are lower", "Land first to clear the runway", "Orbit overhead"], 0, "Give way to an aircraft compelled to land."),
  Q("landing-right-of-way", "An aircraft taxiing on the manoeuvring area must give way to:", ["Aircraft taking off or about to take off", "Vehicles towing aircraft only", "Nothing if cleared to taxi", "Aircraft parked on the apron"], 0, "Taxiing aircraft give way to departing (and landing) aircraft."),

  Q("technical-log", "The main purpose of the aircraft technical log is to:", ["Record flights, defects, rectifications and maintenance status between scheduled maintenance", "Record the pilot's personal flying hours for licensing", "Record the aircraft's basic weight", "Replace the C of A"], 0, "It's the aircraft's working record of flights and defects."),
  Q("technical-log", "A defect discovered during a flight should be:", ["Entered in the technical log by the PIC at the end of the flight", "Reported only if it gets worse", "Recorded in the pilot's personal log book", "Reported to ATC only"], 0, "Enter defects in the tech log so they're dealt with."),
  Q("technical-log", "Rectification of a defect entered in the technical log is certified by:", ["A Certificate of Release to Service", "The PIC's signature", "A new weight schedule", "The ARC"], 0, "A CRS certifies the rectification."),
  Q("technical-log", "Before flight, the technical log should be checked for:", ["Open or deferred defects and hours remaining to the next check", "The previous pilot's licence number", "The weather", "NOTAMs"], 0, "Defects and maintenance status."),

  Q("right-of-way-obligations", "An aircraft that has the right of way should:", ["Maintain its heading and speed", "Climb to show it has seen the other aircraft", "Turn right", "Reduce speed"], 0, "SERA.3210(b)."),
  Q("right-of-way-obligations", "An aircraft giving way should avoid passing:", ["Over, under or in front of the other aircraft, unless well clear and allowing for wake turbulence", "Behind the other aircraft", "To the right of the other aircraft", "Below 500 ft"], 0, "SERA.3210(a)."),
  Q("right-of-way-obligations", "The stand-on aircraft maintains heading and speed mainly so that:", ["Its path is predictable and the give-way aircraft can plan a safe avoiding manoeuvre", "It saves fuel", "It can stay on its flight plan", "ATC can track it"], 0, "Predictability prevents both aircraft manoeuvring into each other."),
  Q("right-of-way-obligations", "The stand-on aircraft sees the give-way aircraft is not taking avoiding action and a collision is likely. It should:", ["Take whatever action best avoids the collision", "Maintain heading and speed regardless", "Turn left", "Transmit a MAYDAY first"], 0, "The PIC is never relieved of collision avoidance responsibility."),
  Q("right-of-way-obligations", "When giving way, the give-way aircraft should take into account:", ["The effect of wake turbulence", "The other aircraft's registration", "Its own fuel price", "The time of day"], 0, "Pass well clear, allowing for wake turbulence.")
];

QUESTIONS.forEach((question, index) => {
  const sameTopicBefore = QUESTIONS.slice(0, index).filter(other => other.topicId === question.topicId).length;
  question.id = `${question.topicId}-${sameTopicBefore}`;
  question.topic = TOPICS.find(topic => topic.id === question.topicId).num;
});
